:pixelated}.magic-chosen>span{padding:16px;border:1px dashed var(--journal-border);border-radius:9px;width:100%;font-size:12px;text-align:center;color:var(--journal-muted)}.magic-filters{display:flex;gap:6px;margin:12px 0}.magic-filters button,.magic-more{padding:10px;background:var(--journal-soft);border:1px solid var(--journal-border);border-radius:7px;font-size:12px}.magic-filters button[aria-pressed=true]{background:var(--journal-selected);font-weight:700}.magic-filters input{width:0;min-width:60px;flex:1;border:1px solid var(--journal-border);background:var(--journal-card);border-radius:7px;padding:8px;font-size:12px}.magic-roster{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px}.magic-roster>button{display:flex;align-items:center;gap:5px;border:1px solid var(--journal-border);border-radius:9px;background:var(--journal-card);padding:7px;font-size:11px;text-align:left;min-width:0}.magic-roster>button[aria-pressed=true]{background:var(--journal-selected);border-color:var(--journal-accent)}.magic-roster img{width:40px;height:40px;object-fit:contain;image-rendering:pixelated}.magic-roster span{flex:1;overflow-wrap:anywhere}.magic-more{margin:12px 0;width:100%}.magic-reward{padding:0;list-style:none;display:grid;grid-template-columns:1fr 1fr;gap:8px}.magic-reward li{font-size:12px;background:var(--journal-soft);padding:10px;border-radius:7px}.magic-reward b{float:right}.magic-rotom{display:flex;align-items:center;justify-content:center;gap:20px;background:var(--journal-soft);border-radius:12px;margin-bottom:20px;padding:16px;font-weight:700}.magic-rotom img{width:90px;height:90px;object-fit:contain;image-rendering:pixelated}.magic-replace select{max-width:60%;padding:10px;border:1px solid var(--journal-border);border-radius:8px;background:var(--journal-card)}footer{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:12px 24px;border-top:1px solid var(--journal-border);background:var(--journal-soft);font-size:12px}footer button{padding:9px 18px;background:var(--journal-card);border:1px solid var(--journal-border);border-radius:8px}.magic-error{color:#b65a65;margin-top:12px}.magic-success{color:var(--journal-accent);margin-top:12px}@media(max-width:600px){.magic-backdrop{padding:8px}.magic-panel{max-height:calc(100dvh - 16px);border-radius:13px}header{padding:14px!important;gap:9px!important}h2{font-size:20px}main{padding:16px}.magic-types{grid-template-columns:repeat(3,1fr)}.magic-recipe{grid-template-columns:1fr}.magic-roster{grid-template-columns:repeat(2,minmax(0,1fr))}.magic-plate-grid{grid-template-columns:repeat(2,1fr)}footer{padding:12px 16px}.magic-reward{grid-template-columns:1fr}}
